{
  "a_sentences": [
    {
      "a_text": "Die Vorinstanz prüft, ob die Versicherung ohne Willkür zum Schluss kommen konnte, dass ihr der Gegenbeweis misslungen ist.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Der Versicherte trägt die Beweislast für den Eintritt des Versicherungsfalls und den Umfang des Anspruchs.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Art. 39 VVG verlangt nach erfolgter Schadensanzeige einen fortgesetzten kooperativen Informationsaustausch zwischen Versicherer und Anspruchsberechtigtem.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Zweck der Versicherung ist die Verteilung tatsächlich eingetretener Schäden auf eine grosse Anzahl gleichartig bedrohter Personen, nicht von bloss möglichen Schäden.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Im Rahmen der Taggeldversicherung besteht aufgrund der Natur der fortlaufenden Leistungen und der Beeinflussbarkeit durch die aktuelle gesundheitliche Verfassung ein höheres Bedürfnis nach schneller Abklärung als in der Invalidenversicherung.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Weist der Versicherer einen Anspruch ohne jegliche oder gestützt auf eine offensichtlich unzulängliche Abklärung ab, überspringt er das vom Gesetzgeber vorgesehene kooperative Verfahren und zwingt den Versicherten in den Prozess, in dem dieser die Behauptungs- und Beweislast trägt.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz erwog, dass es sich so verhalte.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht erachtet die Beschwerde insgesamt als unbegründet und weist sie ab.",
      "b_propositions": ["P8"]
    }
  ]
}
